{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group rule allows RDP from the entire internet",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "CRITICAL",
      "explanation": "The ingress rule for port 3389 (RDP) is open to 0.0.0.0/0, exposing the Windows instance to brute-force attacks and unauthorized remote access from any IP address on the internet."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/8\"]\n}",
  "fix_summary": "Restricted the CIDR block for the RDP ingress rule from 0.0.0.0/0 to a private network range (10.0.0.0/8) to prevent public exposure of the Remote Desktop service."
}
